import Link from "next/link";
import EgPlatzhalter from "@/components/Portal/EG/Stamm/EgPlatzhalter";
import { portalNutzer } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";

export const metadata = { title: "Energiegemeinschaft" };

export default async function Seite() {
  const n = await portalNutzer();
  const k = await egBackend().egKontext(n).catch(() => ({ gemeinschaften: [] }));
  const organ = (k.gemeinschaften || []).filter((g) => g.organ);
  return (
    <div className="space-y-6">
      {organ.length > 0 && (
        <ul className="space-y-2">
          {organ.map((g) => (
            <li key={g.id}>
              <Link href={`/portal/eg/${g.id}/verwaltung`} className="font-semibold text-ov-700 hover:text-ov-800">{g.name}: Verwaltung öffnen</Link>
            </li>
          ))}
        </ul>
      )}
      <EgPlatzhalter eyebrow="Mein Portal" titel="Energiegemeinschaft" text="Ihre Teilnahme, Eigendeckung, Ersparnis und Belege an einem Ort." wp="WP6" />
    </div>
  );
}
