          return (
            <li key={s} className={cn("min-w-0 flex-1", !kompakt && "min-w-[92px]")} aria-current={aktiv ? "step" : undefined}>
              <span className={cn("block h-1.5 rounded-full", fertig ? "bg-ov-500" : aktiv ? "bg-ov-500" : aussen ? "bg-ink-200" : "bg-ink-200")} />
