}
RECHNER_DECKUNG = {"knapp": {"verhaeltnis": 0.3}, "ausgewogen": {"verhaeltnis": 0.7}, "reichlich": {"verhaeltnis": 1.5}}
RECHNER_ROLLEN = {"verbraucher": "Ich verbrauche", "erzeuger": "Ich erzeuge", "prosumer": "Beides"}
