class MitgliedFehler(ValueError):
	def __init__(self, msg, status=422, feld=""):
		super().__init__(msg)
		self.status = status
		self.feld = feld


def fehler(msg, feld=""):
	return MitgliedFehler(msg, 422, feld)


def konflikt_fehler(msg):
	return MitgliedFehler(msg, 409)


# ---------------------------------------------------------------- Helfer (wie basis.js)
export class MitgliedFehler extends Error {
  constructor(msg, status = 422, feld = "") {
    super(msg);
    this.status = status;
    this.feld = feld;
  }
}
export const fehler = (msg, feld = "") => new MitgliedFehler(msg, 422, feld);

