import importlib
import inspect
import json

import frappe
from frappe.utils import nowdate

from oekoinvest_app.plattform import eg_modell as M
from oekoinvest_app.plattform import eg_portal_kern as P
from oekoinvest_app.plattform import eg_stamm_kern as K
