content.content:
import Link from "next/link";
import { ArrowUpRight, Info } from "lucide-react";
import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Reveal from "@/components/ui/Reveal";
import Querverweise from "@/components/Reusable/Querverweise";
import { TOOLS } from "./tools";
import { STAND } from "@/lib/rechner/annahmen";

import { SITE } from "@/data/site";

const BASE = SITE.url;

/** Metadaten für eine Rechner-Seite */
export function rechnerMetadata({ pfad, title, description, keywords = [] }) {
  const url = `${BASE}${pfad}`;
  return {
    title,
    description,
    keywords,
    alternates: { canonical: url },
    robots: { index: true, follow: true },
    openGraph: {
      type: "website",
      url,
      siteName: "ÖkoInvest",
      title,
      description,
      images: [{ url: `${BASE}/img/solarpark-himmel.jpg`, width: 1280, height: 852, alt: title }],
    },
    twitter: { card: "summary_large_image", title, description, images: [`${BASE}/img/solarpark-himmel.jpg`] },
  };
}

/**
 * Gemeinsamer Seitenrahmen aller Rechner: kompakter dunkler Hero, Rechner
 * überlappend darunter (above the fold), Erklärung + Annahmen, FAQ,
 * weitere Tools, Querverweise und Abschluss-CTA. Liefert WebApplication-Schema.
 */
export default function RechnerSeite({
  pfad,
  toolId,
  breadcrumb,
  eyebrow,
  title,
  lead,
  chips = [],
  app,
  rechner,
  erklaerung,
  annahmen = [],
  quellen = [],
  faq = [],
  faqTitel = "Häufige Fragen",
  querverweise = [],
  cta,
}) {
  const url = `${BASE}${pfad}`;
  const schema = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "WebApplication",
        "@id": `${url}/#app`,
        name: app.name,
        url,
        description: app.description,
        applicationCategory: "FinanceApplication",
        operatingSystem: "Web",
        browserRequirements: "Requires JavaScript",
        inLanguage: "de-DE",
        isAccessibleForFree: true,
        featureList: app.featureList,
        offers: { "@type": "Offer", price: "0", priceCurrency: "EUR" },
        publisher: { "@id": `${BASE}/#organization` },
      },
      {
        "@type": "WebPage",
        "@id": `${url}/#webpage`,
        url,
        name: app.name,
        isPartOf: { "@id": `${BASE}/#website` },
        about: { "@id": `${BASE}/#organization` },
        dateModified: new Date().toISOString().split("T")[0],
        mainEntity: { "@id": `${url}/#app` },
      },
    ],
  };

  return (
    <div>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />

      <PageHero
        variant="dark"
        breadcrumbs={[{ name: "Rechner & Tools", href: "/rechner" }, { name: breadcrumb }]}
        eyebrow={eyebrow}
        title={title}
        lead={lead}
        points={chips}
        className="[&>div.ov-container]:pb-28 md:[&>div.ov-container]:pb-36"
      />

      {/* Rechner überlappt den Hero – sofort sichtbar */}
      <section aria-label="Rechner" className="relative z-10 -mt-20 pb-6 md:-mt-28 md:pb-10">
        <div className="ov-container">{rechner}</div>
      </section>

      <Section tone="white" space="md">
        <div className="grid gap-10 lg:grid-cols-[1.1fr_0.9fr] lg:gap-16">
          <div>{erklaerung}</div>
          <Reveal>
            <AnnahmenBox punkte={annahmen} quellen={quellen} />
          </Reveal>
        </div>
      </Section>

      {faq.length > 0 && (
        <Section tone="sand" space="md">
          <div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
            <SectionHeading
              eyebrow="Häufige Fragen"
              title={faqTitel}
              lead="Ihre Frage ist nicht dabei? Unser Projektteam beantwortet sie persönlich."
            />
            <Faq items={faq} />
          </div>
        </Section>
      )}

      <WeitereRechner ohne={toolId} />
      <Querverweise items={querverweise} />
      <CtaBand {...cta} />
    </div>
  );
}

// src/app/rechner/energy-sharing/page.js – Energy Sharing / Energiegemeinschaft DE, AT, CH

import Link from "next/link";
import RechnerSeite, { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import EnergySharingRechner from "@/components/Rechner/EnergySharingRechner";
import { GEMEINSCHAFTEN } from "@/lib/invest/markt";
import { MIXE, SPEICHER_PLUS } from "@/lib/rechner/energySharing";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/rechner/energy-sharing";
const R = GEMEINSCHAFTEN.rechner;

export const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Energy-Sharing-Rechner DE, AT, CH | ÖkoInvest",
  description:
    "Energiegemeinschaft rechnen: geteilter Strom, Netzentgelt-Abschlag (EEG lokal/regional, LEG), Vorteil je Teilnehmer und Erlös des Erzeugers – DE, AT, CH.",
  keywords: ["Energy Sharing Rechner", "Energiegemeinschaft Rechner", "EEG Österreich Netzentgelt", "LEG Schweiz Rechner", "§ 42c EnWG", "Bürgerenergiegemeinschaft"],
});

const at = R.at.rabatte;
const ch = R.ch.rabatte;

const FAQ = [
  {
    q: "Was ist Energy Sharing?",
    a: "Beim Energy Sharing nutzen mehrere Haushalte, Betriebe oder Gemeinden gemeinsam den Strom einer Anlage in ihrer Nähe – über das öffentliche Netz. Gezählt wird jede Viertelstunde: Was die Anlage in dieser Zeit erzeugt und die Teilnehmenden gleichzeitig verbrauchen, ist geteilter Strom. Den Rest liefert wie bisher der eigene Stromlieferant.",
  },
  {
    q: "Wo lohnt sich eine Energiegemeinschaft am meisten?",
