const ELWG = [
  { icon: Repeat, title: "Bis zu fünf Gemeinschaften", text: "Ein Zählpunkt kann an bis zu fünf gemeinsamen Energienutzungen teilnehmen; Teilnahmefaktor ganzzahlig, zusammen höchstens 100 % (ElWG § 71 Abs. 5)." },
